 static synchronized String prompt(Context c,String key)throws Exception{if(prompts==null)try(InputStream in=c.getAssets().open("agent-prompts.json")){prompts=new JSONObject(new String(NativeData.readStream(in,128*1024),StandardCharsets.UTF_8));}return prompts.getString(key);}
